        assert!(code.contains("BigInt f({required BigInt a, required BigInt b}) {"), "{code}");
        assert!(code.contains("w.writeI128(a);"), "{code}");
        assert!(code.contains("w.writeU128(b);"), "{code}");
        assert!(code.contains("final _ret = r.readI128();"), "{code}");
