    #[test]
    fn vec_numeric_maps_to_typed_list_symmetrically() {
        // Param AND return of `Vec<i32>` are both `Int32List` (symmetric).
        // The decode collects into the typed container.
        let code = emit_src("#[bridge(sync)] pub fn f(xs: Vec<i32>) -> Vec<i32> { xs }");
        assert!(code.contains("Int32List f({required Int32List xs}) {"), "{code}");
        assert!(
            code.contains("final _ret = r.readI32List(r.readLen());"),
            "{code}"
        );
    }

    #[test]
    fn vec_numeric_is_bulk_coded_not_looped() {
        // The deficit this replaced: decode was
        // `Int32List.fromList(List.generate(r.readLen(), (_) => r.readI32()))`
        // — n boxed ints into a growable list, then a copy into the typed one —
        // and encode was a per-element loop. Both are now one bulk call.
        // The *wire* is untouched, which is why the length prefix is still
        // written and read here by the caller; the byte-for-byte equality of
        // the bulk call and the element loop it replaces is pinned in the
        // runtime suites (runtime/dart/test/binary_codec_bulk_test.dart and
        // runtime/rust/src/codec.rs), not here.
        let code = emit_src("#[bridge(sync)] pub fn f(xs: Vec<i32>) -> Vec<i32> { xs }");
        assert!(code.contains("w.writeLen(xs.length);"), "{code}");
        assert!(code.contains("w.writeI32List(xs);"), "{code}");
        assert!(!code.contains("w.writeI32(it"), "no element loop left: {code}");
        assert!(
            !code.contains("List.generate(r.readLen(), (_) => r.readI32())"),
            "no List.generate left: {code}"
        );
    }

    #[test]
    fn every_typed_list_element_maps() {
        // The full §1 matrix, in one place.
        // `Vec<u8>` is NOT here: it parses to `Type::Bytes` (the memcpy fast
        // path, `Uint8List` via `readBytes`), covered by `bytes and arrays`.
        // `typed_list_class(U8)` still returns `Uint8List` for completeness,
        // but `List(U8)` never reaches emit.
        //
        // Both columns per row, because `typed_list_entry` carries both and the
        // two have to agree: the declared Dart class and the codec method that
        // produces it. Whether the bulk arm is *taken* is the runtime's
        // compile-time decision (`bulkTypedDataOk`/`bulkI64Ok` in
        // binary_codec.dart); the emitted shape is the same on every backend.
        for (rust, dart, bulk) in [
            ("i8", "Int8List", "readI8List"),
            ("i16", "Int16List", "readI16List"),
            ("i32", "Int32List", "readI32List"),
            ("i64", "Int64List", "readI64List"),
            ("u16", "Uint16List", "readU16List"),
            ("u32", "Uint32List", "readU32List"),
            ("f32", "Float32List", "readF32List"),
            ("f64", "Float64List", "readF64List"),
        ] {
            let code = emit_src(&format!(
                "#[bridge(sync)] pub fn f(xs: Vec<{rust}>) -> Vec<{rust}> {{ xs }}"
            ));
            assert!(code.contains(&format!("{dart} f({{required {dart} xs}}) {{")), "{rust}: {code}");
            assert!(
                code.contains(&format!("r.{bulk}(r.readLen())")),
                "{rust}: {code}"
            );
            assert!(
                code.contains(&format!("w.write{}List(xs);", &bulk[4..bulk.len() - 4])),
                "{rust}: {code}"
            );
        }
    }

    #[test]
    fn vec_i64_takes_the_bulk_call_like_every_other_typed_list() {
        // One emitted shape on every backend — the JS-number exclusion is the
        // runtime's (`bulkI64Ok`), not codegen's, because a `Vec<i64>` written
        // by a *generic* data class arrives as a plain `List<int>` whose
        // representation is only knowable at runtime. Codegen that tried to
        // decide it would have to decide it wrongly for that case.
        let code = emit_src("#[bridge(sync)] pub fn f(xs: Vec<i64>) -> Vec<i64> { xs }");
        assert!(code.contains("Int64List f({required Int64List xs}) {"), "{code}");
        assert!(code.contains("w.writeI64List(xs);"), "{code}");
        assert!(code.contains("r.readI64List(r.readLen())"), "{code}");
        assert!(!code.contains("w.writeI64(it"), "no element loop left: {code}");
        assert!(
            !code.contains("Int64List.fromList(List.generate("),
            "no List.generate left: {code}"
        );
    }

    #[test]
    fn an_i64_array_takes_the_bulk_call_with_its_length_from_the_type() {
        // `[i64; N]` rides the same selection: N elements, no length prefix,
        // and the wrong-length check still on the encode side.
        let code = emit_src("#[bridge(sync)] pub fn f(xs: [i64; 4]) -> [i64; 4] { xs }");
        assert!(code.contains("w.checkArrayLength(xs.length, 4);"), "{code}");
        assert!(code.contains("w.writeI64List(xs);"), "{code}");
        assert!(code.contains("r.readI64List(4)"), "{code}");
    }

    #[test]
    fn non_numeric_vecs_stay_generic_list() {
        // BigInt-backed and non-scalar elements have no typed list.
        for (rust, dart) in [
            ("u64", "List<BigInt>"),
            ("i128", "List<BigInt>"),
            ("u128", "List<BigInt>"),
            ("bool", "List<bool>"),
            ("String", "List<String>"),
            ("char", "List<String>"),
            ("usize", "List<int>"),
            ("isize", "List<int>"),
        ] {
            let code = emit_src(&format!(
                "#[bridge(sync)] pub fn f() -> Vec<{rust}> {{ todo!() }}"
            ));
            assert!(code.contains(&format!("{dart} f() {{")), "{rust}: {code}");
        }
    }

    #[test]
    fn typed_lists_compose_through_nesting() {
        // Vec<Vec<i32>> -> List<Int32List> (outer stays generic, inner typed).
        let vv = emit_src("#[bridge(sync)] pub fn f() -> Vec<Vec<i32>> { todo!() }");
        assert!(vv.contains("List<Int32List> f() {"), "{vv}");
        // The bulk read composes as the inner decode expression: the outer
        // generic list still generates, each element is one bulk call.
        assert!(
            vv.contains("List.generate(r.readLen(), (_) => r.readI32List(r.readLen()))"),
            "{vv}"
        );

        // HashMap<String, Vec<f64>> -> Map<String, Float64List>.
        let m = emit_src(
            "#[bridge(sync)] pub fn f() -> HashMap<String, Vec<f64>> { todo!() }",
        );
        assert!(m.contains("Map<String, Float64List> f() {"), "{m}");
        assert!(m.contains("r.readF64List(r.readLen())"), "{m}");

        // Option<Vec<i32>> -> Int32List?.
        let o = emit_src("#[bridge(sync)] pub fn f(x: Option<Vec<i32>>) -> Option<Vec<i32>> { x }");
        assert!(o.contains("Int32List? f({Int32List? x}) {"), "{o}");
    }

    #[test]
